            return this;
        }

        public SubscriptionHandle Subscribe() => new(conn, Applied, Error, querySqls.ToArray());
    }

    public abstract partial class Reducer
    {
        private Reducer() { }
    }

    public abstract partial class Procedure
    {
        private Procedure() { }
    }

    public sealed class DbConnection : DbConnectionBase<DbConnection, RemoteTables, Reducer>
    {
        public override RemoteTables Db { get; }
        public readonly RemoteReducers Reducers;
        public readonly RemoteProcedures Procedures;

        public DbConnection()
        {
            Db = new(this);
            Reducers = new(this);
            Procedures = new(this);
        }

        protected override IEventContext ToEventContext(Event<Reducer> Event) =>
        new EventContext(this, Event);

        protected override IReducerEventContext ToReducerEventContext(ReducerEvent<Reducer> reducerEvent) =>
        new ReducerEventContext(this, reducerEvent);

        protected override ISubscriptionEventContext MakeSubscriptionEventContext() =>
        new SubscriptionEventContext(this);

        protected override IErrorContext ToErrorContext(Exception exception) =>
        new ErrorContext(this, exception);

        protected override IProcedureEventContext ToProcedureEventContext(ProcedureEvent procedureEvent) =>
        new ProcedureEventContext(this, procedureEvent);

        protected override bool Dispatch(IReducerEventContext context, Reducer reducer)
        {
            var eventContext = (ReducerEventContext)context;
            return reducer switch
            {
                Reducer.AddChunks args => Reducers.InvokeAddChunks(eventContext, args),
                Reducer.ChangeStats args => Reducers.InvokeChangeStats(eventContext, args),
                Reducer.ClaimAdmin args => Reducers.InvokeClaimAdmin(eventContext, args),
                Reducer.ClearChunks args => Reducers.InvokeClearChunks(eventContext, args),
                Reducer.DespawnEnemy args => Reducers.InvokeDespawnEnemy(eventContext, args),
                Reducer.GainXp args => Reducers.InvokeGainXp(eventContext, args),
                Reducer.GiveItem args => Reducers.InvokeGiveItem(eventContext, args),
                Reducer.PickupDrop args => Reducers.InvokePickupDrop(eventContext, args),
                Reducer.PlaceBuilding args => Reducers.InvokePlaceBuilding(eventContext, args),
                Reducer.ReleaseAdmin args => Reducers.InvokeReleaseAdmin(eventContext, args),
                Reducer.RemoveBuilding args => Reducers.InvokeRemoveBuilding(eventContext, args),
                Reducer.RemoveItem args => Reducers.InvokeRemoveItem(eventContext, args),
                Reducer.ReportEnemyHit args => Reducers.InvokeReportEnemyHit(eventContext, args),
                Reducer.ReportMovement args => Reducers.InvokeReportMovement(eventContext, args),
                Reducer.SetUsername args => Reducers.InvokeSetUsername(eventContext, args),
                Reducer.SpawnEnemy args => Reducers.InvokeSpawnEnemy(eventContext, args),
                Reducer.ToggleDebug args => Reducers.InvokeToggleDebug(eventContext, args),
                Reducer.UpdateInventory args => Reducers.InvokeUpdateInventory(eventContext, args),
                Reducer.UpsertEnemyTemplate args => Reducers.InvokeUpsertEnemyTemplate(eventContext, args),
                Reducer.UpsertItemStats args => Reducers.InvokeUpsertItemStats(eventContext, args),
                _ => throw new ArgumentOutOfRangeException("Reducer", $"Unknown reducer {reducer}")
            };
        }

        public SubscriptionBuilder SubscriptionBuilder() => new(this);
        public event Action<ReducerEventContext, Exception> OnUnhandledReducerError
        {
            add => Reducers.InternalOnUnhandledReducerError += value;
            remove => Reducers.InternalOnUnhandledReducerError -= value;
        }
    }
}
